/** The bridge the runtime speaks through: generic protocol in, typed store out. */
class BillingStoreResolver(
    private val store: BillingStore,
    model: Model,
) : StateResolver {
    private val questions = BillingStoreQuestions(model)

    override fun fetchByKey(shape: String, key: StoreKey): Row? = when (shape) {
        "Customer" -> store.customer(key)?.toRow()
        "CorrectEmail" -> store.correctEmail(key)?.toRow()
        "Invoice" -> store.invoice(key)?.toRow()
        "LineItem" -> store.lineItem(key)?.toRow()
        "Payment" -> store.payment(key)?.toRow()
        "Receipt" -> store.receipt(key)?.toRow()
        "ReceiptEmail" -> store.receiptEmail(key)?.toRow()
        "Reminder" -> store.reminder(key)?.toRow()
        "Issuance" -> store.issuance(key)?.toRow()
        "DueChangeRefusal" -> store.dueChangeRefusal(key)?.toRow()
        "ArchiveRequest" -> store.archiveRequest(key)?.toRow()
        "UnarchiveRequest" -> store.unarchiveRequest(key)?.toRow()
        "UnarchiveNotice" -> store.unarchiveNotice(key)?.toRow()
        else -> null
    }

    override fun fetchAll(shape: String): List<Row> = when (shape) {
        "Customer" -> store.allCustomers().map { it.toRow() }
        "CorrectEmail" -> store.allCorrectEmails().map { it.toRow() }
        "Invoice" -> store.allInvoices().map { it.toRow() }
        "LineItem" -> store.allLineItems().map { it.toRow() }
        "Payment" -> store.allPayments().map { it.toRow() }
        "Receipt" -> store.allReceipts().map { it.toRow() }
        "ReceiptEmail" -> store.allReceiptEmails().map { it.toRow() }
        "Reminder" -> store.allReminders().map { it.toRow() }
        "Issuance" -> store.allIssuances().map { it.toRow() }
        "DueChangeRefusal" -> store.allDueChangeRefusals().map { it.toRow() }
        "ArchiveRequest" -> store.allArchiveRequests().map { it.toRow() }
        "UnarchiveRequest" -> store.allUnarchiveRequests().map { it.toRow() }
        "UnarchiveNotice" -> store.allUnarchiveNotices().map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchReferencing(shape: String, field: String, target: Ref.Persisted): List<Row> = when {
        shape == "CorrectEmail" && field == "customer" -> store.correctEmailsByCustomer(target).map { it.toRow() }
        shape == "Invoice" && field == "customer" -> store.invoicesByCustomer(target).map { it.toRow() }
        shape == "LineItem" && field == "invoice" -> store.lineItemsByInvoice(target).map { it.toRow() }
        shape == "Payment" && field == "invoice" -> store.paymentsByInvoice(target).map { it.toRow() }
        shape == "Receipt" && field == "invoice" -> store.receiptsByInvoice(target).map { it.toRow() }
        shape == "ReceiptEmail" && field == "receipt" -> store.receiptEmailsByReceipt(target).map { it.toRow() }
        shape == "Reminder" && field == "invoice" -> store.remindersByInvoice(target).map { it.toRow() }
        shape == "Issuance" && field == "invoice" -> store.issuancesByInvoice(target).map { it.toRow() }
        shape == "DueChangeRefusal" && field == "invoice" -> store.dueChangeRefusalsByInvoice(target).map { it.toRow() }
        shape == "ArchiveRequest" && field == "invoice" -> store.archiveRequestsByInvoice(target).map { it.toRow() }
        shape == "UnarchiveRequest" && field == "invoice" -> store.unarchiveRequestsByInvoice(target).map { it.toRow() }
        shape == "UnarchiveNotice" && field == "invoice" -> store.unarchiveNoticesByInvoice(target).map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchCandidates(shape: String, filter: QF): List<Row> {
        if (shape == "Receipt")
            questions.unemailedReceiptCandidates.match(filter)?.let { h -> return store.unemailedReceiptCandidates().map { it.toRow() } }
        if (shape == "Invoice")
            questions.overdueInvoiceCandidates.match(filter)?.let { h -> return store.overdueInvoiceCandidates(h.date(0)).map { it.toRow() } }
        if (shape == "Invoice")
            questions.actionableOverdueCandidates.match(filter)?.let { h -> return store.actionableOverdueCandidates(h.date(0)).map { it.toRow() } }
        if (shape == "Invoice")
            questions.issuedInvoiceCandidates.match(filter)?.let { h -> return store.issuedInvoiceCandidates().map { it.toRow() } }
        if (shape == "Invoice")
            questions.archivedInvoiceCandidates.match(filter)?.let { h -> return store.archivedInvoiceCandidates().map { it.toRow() } }
        if (shape == "Invoice")
            questions.remindOverdueCandidates.match(filter)?.let { h -> return store.remindOverdueCandidates(h.date(0), h.date(1)).map { it.toRow() } }
        if (shape == "LineItem")
            questions.never1Candidates.match(filter)?.let { h -> return store.never1Candidates().map { it.toRow() } }
        if (shape == "LineItem")
            questions.never2Candidates.match(filter)?.let { h -> return store.never2Candidates().map { it.toRow() } }
        if (shape == "Payment")
            questions.never3Candidates.match(filter)?.let { h -> return store.never3Candidates().map { it.toRow() } }
        return fetchAll(shape) // unrecognized filters fall back to the scan floor
    }

    override fun fetchCaptures(instance: Ref.Persisted, refinement: String): Map<String, Any?>? = when (refinement) {
        "ArchivedInvoice" -> store.archivedInvoiceCapture(instance)?.toValues()
        else -> null
    }
}

private fun List<QConst>.date(i: Int): LocalDate = (this[i] as QConst.QDate).v
private fun List<QConst>.instant(i: Int): Instant = (this[i] as QConst.QDateTime).v

// ── row mappers: the generic wire format <-> the typed rows ──

fun Row.toCustomerRow(): CustomerRow = CustomerRow(
    key = key,
    name = fields["name"] as String,
    email = fields["email"] as String,
    signedUpOn = fields["signedUpOn"] as Instant,
    largestPayment = fields["largestPayment"] as BigDecimal,
)

fun CustomerRow.toRow(): Row = Row("Customer", key, buildMap {
    put("name", name)
    put("email", email)
    put("signedUpOn", signedUpOn)
    put("largestPayment", largestPayment)
})

fun Row.toCorrectEmailRow(): CorrectEmailRow = CorrectEmailRow(
    key = key,
    customer = fields["customer"] as Ref.Persisted,
    corrected = fields["corrected"] as String,
)

fun CorrectEmailRow.toRow(): Row = Row("CorrectEmail", key, buildMap {
    put("customer", customer)
    put("corrected", corrected)
})

fun Row.toInvoiceRow(): InvoiceRow = InvoiceRow(
    key = key,
    customer = fields["customer"] as Ref.Persisted,
    due = fields["due"] as LocalDate,
    reference = fields["reference"] as String,
    issuedOn = fields["issuedOn"] as Instant,
)

fun InvoiceRow.toRow(): Row = Row("Invoice", key, buildMap {
    put("customer", customer)
    put("due", due)
    put("reference", reference)
    put("issuedOn", issuedOn)
})

fun Row.toLineItemRow(): LineItemRow = LineItemRow(
    key = key,
    invoice = fields["invoice"] as Ref.Persisted,
    description = fields["description"] as String,
    price = fields["price"] as BigDecimal,
    quantity = (fields["quantity"] as Number).toInt(),
)

fun LineItemRow.toRow(): Row = Row("LineItem", key, buildMap {
    put("invoice", invoice)
    put("description", description)
    put("price", price)
    put("quantity", quantity)
})

fun Row.toPaymentRow(): PaymentRow = PaymentRow(
    key = key,
    invoice = fields["invoice"] as Ref.Persisted,
    amount = fields["amount"] as BigDecimal,
    receivedOn = fields["receivedOn"] as Instant,
)

fun PaymentRow.toRow(): Row = Row("Payment", key, buildMap {
    put("invoice", invoice)
    put("amount", amount)
    put("receivedOn", receivedOn)
})

fun Row.toReceiptRow(): ReceiptRow = ReceiptRow(
    key = key,
    invoice = fields["invoice"] as Ref.Persisted,
    sentOn = fields["sentOn"] as Instant,
)

fun ReceiptRow.toRow(): Row = Row("Receipt", key, buildMap {
