    put("requestedDue", requestedDue)
    put("reason", reason)
    put("refusedOn", refusedOn)
})

fun Row.toArchiveRequestRow(): ArchiveRequestRow = ArchiveRequestRow(
    key = key,
    invoice = fields["invoice"] as Ref.Persisted,
)

fun ArchiveRequestRow.toRow(): Row = Row("ArchiveRequest", key, buildMap {
    put("invoice", invoice)
})

fun Row.toUnarchiveRequestRow(): UnarchiveRequestRow = UnarchiveRequestRow(
    key = key,
    invoice = fields["invoice"] as Ref.Persisted,
)

fun UnarchiveRequestRow.toRow(): Row = Row("UnarchiveRequest", key, buildMap {
    put("invoice", invoice)
})

fun Row.toUnarchiveNoticeRow(): UnarchiveNoticeRow = UnarchiveNoticeRow(
    key = key,
    invoice = fields["invoice"] as Ref.Persisted,
    wasArchivedOn = fields["wasArchivedOn"] as LocalDate,
    noticedOn = fields["noticedOn"] as Instant,
)

fun UnarchiveNoticeRow.toRow(): Row = Row("UnarchiveNotice", key, buildMap {
    put("invoice", invoice)
    put("wasArchivedOn", wasArchivedOn)
    put("noticedOn", noticedOn)
})

fun Map<String, Any?>.toArchivedInvoiceCapture(): ArchivedInvoiceCapture = ArchivedInvoiceCapture(
    archivedOn = this["archivedOn"] as LocalDate,
)

fun ArchivedInvoiceCapture.toValues(): Map<String, Any?> = buildMap {
    put("archivedOn", archivedOn)
}
